def get_omega_M(n):
    if n < 34:
        return -1 # Indicates 2023 does not divide n!

    # We need to find the number of distinct prime factors of M = n! / (7 * 17^2)
    # M = product_{p <= n} p^(e_p(n!) - delta_p)
    # where delta_7 = 1, delta_17 = 2, and 0 otherwise.
    # A prime p is a factor of M if e_p(n!) - delta_p > 0.

    primes = []
    is_prime = [True] * (n + 1)
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                is_prime[i] = False

    omega_M = 0
    for p in primes:
        # calculate e_p(n!)
        ep = 0
        temp_n = n
        while temp_n >= p:
            ep += temp_n // p
            temp_n //= p

        delta = 0
        if p == 7:
            delta = 1
        elif p == 17:
            delta = 2

        if ep - delta > 0:
            omega_M += 1
    return omega_M

results = []
for n in range(1, 200):
    omega = get_omega_M(n)
    if omega != -1:
        num_pairs = 2**omega
        if num_pairs <= 4000:
            results.append(n)
    else:
        # For n < 34, number of pairs is 0.
        # Let's see if they're included.
        pass

print(f"n for which 2023 divides n! and 2^omega <= 4000: {results}")
print(f"Sum of these n: {sum(results)}")

